struct seq_hdr { std::uint32_t seq_id, position, size; };
std::map<std::uint32_t, Group> groups;        // one entry per sequence

void on_part(seq_hdr h, Part p) {
    Group& g = groups[h.seq_id];
    g.parts[h.position - 1] = std::move(p);  // positions are 1-based
    if (g.parts.size() == h.size) { deliver(g); groups.erase(h.seq_id); }
}

